<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\UserRef;
use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Features\Access\UserProfile\Domain\UserProfile;

final class UserProfileUnitTest extends TestCase
{
    public function test_init_store_values(): void
    {
        // @Arrange
        $one = new UserProfile(
            uid: 'one',
            user: new UserRef('one'),
            givenName: 'one',
            familyName: 'one',
            middleName: 'one',
            nickname: 'one',
            preferredUsername: 'one',
            pictureUrl: 'one',
            websiteUrl: 'one',
            gender: 'one',
            birthdate: 'one',
            zoneinfo: 'one',
            locale: 'one',
            phoneNumber: 'one',
            phoneNumberVerified: true,
            addressJson: 'one',
            updatedAt: 'one',
            version: 1,
        );

        // @Act
        $other = $one->toAttributes()->createNewInstance();
        $calculated = UserProfile::calculatedFields();

        // @Assert
        $this->assertEquals([ 'updatedAt'], $calculated);
        $this->assertEquals($one->uid(), $other->uid());
        $this->assertEquals($one->getUser(), $other->getUser());
        $this->assertTrue($one->isUserChanged());
        $this->assertEquals($one->getGivenName(), $other->getGivenName());
        $this->assertTrue($one->isGivenNameChanged());
        $this->assertEquals($one->getFamilyName(), $other->getFamilyName());
        $this->assertTrue($one->isFamilyNameChanged());
        $this->assertEquals($one->getMiddleName(), $other->getMiddleName());
        $this->assertTrue($one->isMiddleNameChanged());
        $this->assertEquals($one->getNickname(), $other->getNickname());
        $this->assertTrue($one->isNicknameChanged());
        $this->assertEquals($one->getPreferredUsername(), $other->getPreferredUsername());
        $this->assertTrue($one->isPreferredUsernameChanged());
        $this->assertEquals($one->getPictureUrl(), $other->getPictureUrl());
        $this->assertTrue($one->isPictureUrlChanged());
        $this->assertEquals($one->getWebsiteUrl(), $other->getWebsiteUrl());
        $this->assertTrue($one->isWebsiteUrlChanged());
        $this->assertEquals($one->getGender(), $other->getGender());
        $this->assertTrue($one->isGenderChanged());
        $this->assertEquals($one->getBirthdate(), $other->getBirthdate());
        $this->assertTrue($one->isBirthdateChanged());
        $this->assertEquals($one->getZoneinfo(), $other->getZoneinfo());
        $this->assertTrue($one->isZoneinfoChanged());
        $this->assertEquals($one->getLocale(), $other->getLocale());
        $this->assertTrue($one->isLocaleChanged());
        $this->assertEquals($one->getPhoneNumber(), $other->getPhoneNumber());
        $this->assertTrue($one->isPhoneNumberChanged());
        $this->assertEquals($one->isPhoneNumberVerified(), $other->isPhoneNumberVerified());
        $this->assertTrue($one->isPhoneNumberVerifiedChanged());
        $this->assertEquals($one->getAddressJson(), $other->getAddressJson());
        $this->assertTrue($one->isAddressJsonChanged());
        $this->assertEquals($one->getVersion(), $other->getVersion());
        $this->assertTrue($one->isVersionChanged());
    }
    public function test_replace_change_values(): void
    {
        // @Arrange
        $base = new UserProfile(
