            phoneNumber: 'one',
            phoneNumberVerified: true,
            addressJson: 'one',
            updatedAt: 'one',
            version: 1,
        );
        $other = new UserProfile(
            uid: 'other',
            user: new UserRef('other'),
            givenName: 'other',
            familyName: 'other',
            middleName: 'other',
            nickname: 'other',
            preferredUsername: 'other',
            pictureUrl: 'other',
            websiteUrl: 'other',
            gender: 'other',
            birthdate: 'other',
            zoneinfo: 'other',
            locale: 'other',
            phoneNumber: 'other',
            phoneNumberVerified: false,
            addressJson: 'other',
            updatedAt: 'other',
            version: 2,
        );

        // @Act
        $one = $base->replace($other->toAttributes());

        // @Assert
        $this->assertEquals($one->uid(), $base->uid());
        $this->assertEquals($one->getUser(), $other->getUser());
        $this->assertTrue($one->isUserChanged($base));
        $this->assertEquals($one->getGivenName(), $other->getGivenName());
        $this->assertTrue($one->isGivenNameChanged($base));
        $this->assertEquals($one->getFamilyName(), $other->getFamilyName());
        $this->assertTrue($one->isFamilyNameChanged($base));
        $this->assertEquals($one->getMiddleName(), $other->getMiddleName());
        $this->assertTrue($one->isMiddleNameChanged($base));
        $this->assertEquals($one->getNickname(), $other->getNickname());
        $this->assertTrue($one->isNicknameChanged($base));
        $this->assertEquals($one->getPreferredUsername(), $other->getPreferredUsername());
        $this->assertTrue($one->isPreferredUsernameChanged($base));
        $this->assertEquals($one->getPictureUrl(), $other->getPictureUrl());
        $this->assertTrue($one->isPictureUrlChanged($base));
        $this->assertEquals($one->getWebsiteUrl(), $other->getWebsiteUrl());
        $this->assertTrue($one->isWebsiteUrlChanged($base));
        $this->assertEquals($one->getGender(), $other->getGender());
        $this->assertTrue($one->isGenderChanged($base));
