        $this->assertTrue($one->isBirthdateChanged($base));
        $this->assertEquals($one->getZoneinfo(), $other->getZoneinfo());
        $this->assertTrue($one->isZoneinfoChanged($base));
        $this->assertEquals($one->getLocale(), $other->getLocale());
        $this->assertTrue($one->isLocaleChanged($base));
        $this->assertEquals($one->getPhoneNumber(), $other->getPhoneNumber());
