    public function test_json_compare(): void
    {
        // @Arrange
        $one = new UserProfile(
            uid: 'one',
            user: new UserRef('one'),
            givenName: 'one',
            familyName: 'one',
            middleName: 'one',
            nickname: 'one',
            preferredUsername: 'one',
            pictureUrl: 'one',
            websiteUrl: 'one',
            gender: 'one',
            birthdate: 'one',
            zoneinfo: 'one',
            locale: 'one',
            phoneNumber: 'one',
            phoneNumberVerified: true,
            addressJson: 'one',
            updatedAt: 'one',
            version: 1,
        );

        // @Act
        $json = $one->asPublicJson();

        // @Assert
        $this->assertEquals('one', $json['uid']);
        $this->assertEquals('one', $json['user']['$ref']);
        $this->assertEquals('one', $json['givenName']);
        $this->assertEquals('one', $json['familyName']);
        $this->assertEquals('one', $json['middleName']);
        $this->assertEquals('one', $json['nickname']);
        $this->assertEquals('one', $json['preferredUsername']);
        $this->assertEquals('one', $json['pictureUrl']);
        $this->assertEquals('one', $json['websiteUrl']);
        $this->assertEquals('one', $json['gender']);
        $this->assertEquals('one', $json['birthdate']);
        $this->assertEquals('one', $json['zoneinfo']);
        $this->assertEquals('one', $json['locale']);
        $this->assertEquals('one', $json['phoneNumber']);
        $this->assertEquals(true, $json['phoneNumberVerified']);
        $this->assertEquals('one', $json['updatedAt']);
        $this->assertEquals(1, $json['version']);
    }
